def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    own = []
    opp = []
    for h in history:
        own.append(h[0])
        opp.append(h[1])

    opp_def = sum(1 for x in opp if x == 'D')
    own_def = sum(1 for x in own if x == 'D')
    last_opp = opp[-1]

    if opp_def == 0:
        if n >= 90 and rng.random() < 0.02:
            return 'D'
        return 'C'

    if own_def == 0 and n >= 8:
        return 'D'

    if last_opp == 'C':
        recent = opp[-10:]
        recent_def = sum(1 for x in recent if x == 'D')
        if recent_def <= 1:
            if n >= 85 and rng.random() < 0.15:
                return 'D'
            return 'C'
        if recent_def >= 6:
            return 'D'
        if rng.random() < 0.88:
            return 'C'
        return 'D'

    if opp_def * 3 >= n:
        return 'D'
    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'
    if n >= 3 and opp[-1] == 'D' and opp[-2] == 'D' and opp[-3] == 'D':
        return 'D'
    if rng.random() < 0.55:
        return 'D'
    return 'C'
